//! The window and tray icon: assets/brand/roksync-icon.png (generated by
//! `examples/brand_icons.rs`) scaled to the requested size, with a green dot while sync is live.

use image::imageops::{self, FilterType};

const PNG: &[u8] = include_bytes!("../assets/brand/roksync-icon.png");
const INK: [u8; 3] = [0x0D, 0x0D, 0x0F];
const LIVE: [u8; 3] = [0x7C, 0xFF, 0x6B];

/// `size`×`size` RGBA pixels, rows top to bottom.
pub fn rgba(size: u32, live: bool) -> Vec<u8> {
    let src = image::load_from_memory_with_format(PNG, image::ImageFormat::Png).expect("bundled icon").to_rgba8();
    let mut img = imageops::resize(&src, size, size, FilterType::Lanczos3);
    if live {
        // anti-aliased green dot in the top-right corner inside an ink ring
        let s = size as f32;
        let (cx, cy) = (s * 0.78, s * 0.22);
        let (dot, ring) = (s * 0.15, s * 0.22);
        for (x, y, p) in img.enumerate_pixels_mut() {
            let d = ((x as f32 + 0.5 - cx).powi(2) + (y as f32 + 0.5 - cy).powi(2)).sqrt();
            let a_ring = (ring - d + 0.5).clamp(0.0, 1.0);
            let a_dot = (dot - d + 0.5).clamp(0.0, 1.0);
            if a_ring <= 0.0 {
                continue;
            }
            for i in 0..3 {
                let under = p[i] as f32 * (1.0 - a_ring) + INK[i] as f32 * a_ring;
                p[i] = (under * (1.0 - a_dot) + LIVE[i] as f32 * a_dot).round() as u8;
            }
            p[3] = p[3].max((a_ring * 255.0) as u8);
        }
    }
    img.into_raw()
}
